import math

GROUND_TOP = 0.5

def build_agent(sandbox):
    # Define safe positions avoiding forbidden zones
    safe_x = [7.0, 7.75, 9.6]
    safe_y = [3.6, 4.8, 5.0]

    # Create 3x3 grid of beams (9 beams total)
    beams = []
    for x in safe_x:
        for y in safe_y:
            beam = sandbox.add_beam(x, y, 0.5, 0.5, density=2.0)
            beams.append(beam)

    # Anchor the first beam (7.0, 3.6) to ground
    anchor = beams[0]
    sandbox.add_joint(anchor, None, (7.0, 3.6), type='rigid')

    # Connect other beams to anchor with pivot joints
    for beam in beams[1:]:
        # Get the position of the beam to connect
        beam_pos = beam.position
        # Create a pivot joint between anchor and this beam at beam's position
        sandbox.add_joint(anchor, beam, (beam_pos[0], beam_pos[1]), type='pivot')
        sandbox.set_damping(beam, linear=0.5, angular=0.5)
        sandbox.set_material_properties(beam, restitution=0.0)

    # Validate mass and beam count constraints
    total_mass = sandbox.get_structure_mass()
    if total_mass >= sandbox.MAX_STRUCTURE_MASS:
        raise ValueError("Mass exceeds limit")
    if len(sandbox.bodies) > sandbox.MAX_BEAM_COUNT:
        raise ValueError("Beam count exceeds limit")

    return anchor

